                        new_rb = rt_b[:ib] + [na] + rt_b[ib + 1:]
                        delta = (route_cost(new_ra) + route_cost(new_rb)) - (cost_a_before + cost_b_before)
                        if delta < -1e-9:
                            cand = (delta, ra, rb, ia, ib, na, nb, new_ra, new_rb, new_load_ra, new_load_rb)
                            if best is None or cand[0] < best[0] or (cand[0] == best[0] and (cand[1], cand[3], cand[2], cand[4]) < (best[1], best[3], best[2], best[4])):
                                best = cand
        if best is None:
            return False
        delta, ra, rb, ia, ib, na, nb, new_ra, new_rb, new_load_ra, new_load_rb = best
        routes[ra] = new_ra
        routes[rb] = new_rb
        loads[ra] = new_load_ra
        loads[rb] = new_load_rb
        costs[ra] = route_cost(routes[ra])
        costs[rb] = route_cost(routes[rb])
        return True

    # More robust inter-route improvement: apply best improving relocate/swap repeatedly
    for _ in range(8):
        if len(routes) <= 1:
            break
        # occasional cleanup (should not happen)
        if any(len(rt) == 0 for rt in routes):
            routes2 = []
            for rt in routes:
                if rt:
                    routes2.append(rt)
            routes = routes2
            loads = [route_load(rt) for rt in routes]
            costs = [route_cost(rt) for rt in routes]
            if len(routes) <= 1:
                break
        if best_relocate(routes, loads, costs):
            continue
        if best_swap(routes, loads, costs):
            continue
        break

    # Final intra-route 2-opt to absorb moves
    for _ in range(3):
        changed_any = False
        for idx in range(len(routes)):
            new_rt, ok = two_opt_on_route(routes[idx])
            if ok:
                routes[idx] = new_rt
                changed_any = True
        if not changed_any:
            break

    routes = [rt for rt in routes if rt]
    routes.sort(key=lambda r: (r[0], len(r)))
    return routes
